 android.graphics.Bitmap poster(String address)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);try{if(c.getResponseCode()!=200)return null;byte[] bytes;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>2*1024*1024)return null;out.write(b,0,n);}bytes=out.toByteArray();}android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>400||options.outHeight/options.inSampleSize>500)options.inSampleSize*=2;options.inJustDecodeBounds=false;return android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);}finally{c.disconnect();}}
