 void updateNowNext(){final TvPlayer target=player;final JSONObject channel=channelQueue.optJSONObject(channelIndex);if(channel==null)return;worker.submit(()->{try{JSONArray listings=xmlListings(channel);List<GuideModel.Program> programs=guidePrograms(channel,listings);long now=System.currentTimeMillis();String current="",next="";for(GuideModel.Program p:programs){String value=android.text.format.DateFormat.getTimeFormat(IptvActivity.this).format(new Date(p.start))+" – "+android.text.format.DateFormat.getTimeFormat(IptvActivity.this).format(new Date(p.end))+"  "+p.title;if(p.start<=now&&p.end>now)current="Now: "+value;else if(p.start>now&&next.isEmpty())next="Next: "+value;}final String text=current+(current.isEmpty()||next.isEmpty()?"":"\n")+next;runOnUiThread(()->{if(player==target)target.setSchedule(text);});}catch(Exception ignored){runOnUiThread(()->{if(player==target)target.setSchedule("");});}});}
 String accountIdentity="",accountKey="";
 String favoriteKey(){String identity=server+"\n"+user;if(identity.equals(accountIdentity)&&!accountKey.isEmpty())return accountKey;try{byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest((server+"\n"+user).getBytes("UTF-8"));StringBuilder out=new StringBuilder("favorites_");for(byte b:hash)out.append(String.format("%02x",b&255));accountIdentity=identity;accountKey=out.toString();return accountKey;}catch(Exception e){throw new IllegalStateException();}}
