 void toggleFavorite(String kind,JSONObject item){if(demo){message("Favorites are saved when you connect a provider.");return;}try{JSONArray next=new JSONArray();boolean removed=false;String id=itemId(kind,item);for(int i=0;i<favorites.length();i++){JSONObject f=favorites.getJSONObject(i);if(kind.equals(f.optString("kind"))&&id.equals(f.optString("id")))removed=true;else next.put(f);}if(!removed){JSONObject f=new JSONObject();f.put("kind",kind);f.put("id",id);f.put("item",item);next.put(f);}store.put(favoriteKey(),next.toString());favorites=next;Toast.makeText(this,removed?"Removed from favorites":"Added to favorites",Toast.LENGTH_SHORT).show();current.run();}catch(Exception e){message("Could not save this favorite securely.");}}
 void showDetails(String kind,JSONObject item,JSONArray data,int index){load(()->{String action=kind.equals("series")?"get_series_info":"get_vod_info",id=kind.equals("series")?"&series_id=":"&vod_id=";JSONObject response;try{response=new JSONObject(fetch(api(action,id+enc(itemId(kind,item)))));}catch(Exception e){response=new JSONObject();}JSONObject info=response.optJSONObject("info");if(info==null)info=new JSONObject();String plot=info.optString("plot",info.optString("description","No description supplied."));String meta=info.optString("genre","")+"  "+info.optString("releaseDate",info.optString("releasedate",""))+"  "+info.optString("duration","");return ()->new AlertDialog.Builder(this).setTitle(item.optString("name","Title")).setMessage(meta+"\n\n"+plot).setPositiveButton(kind.equals("series")?"Seasons":"Watch",(d,w)->{if(kind.equals("series"))episodes(itemId(kind,item));else try{channelQueue=null;episodeQueue=null;episodeIndex=-1;String url=stream("movie",itemId(kind,item),item.optString("container_extension","mp4"));go(()->play(item.optString("name"),url));}catch(Exception e){message("Unsupported video identifier");}}).setNeutralButton(isFavorite(kind,item)?"Remove favorite":"Add favorite",(d,w)->toggleFavorite(kind,item)).setNegativeButton("Close",null).show();});}
