 void startSupplement(){if(demo||m3uMode||server.isEmpty()||user.isEmpty())return;String key=favoriteKey();if(supplement!=null&&!supplement.scope.equals(key)){supplement.close();supplement=null;}if(supplement==null)supplement=new EpgSupplement(this,key);final EpgSupplement target=supplement;guideWorker.submit(()->{try{target.loadCached();supplementChanged();target.refresh(()->!isFinishing()&&!isDestroyed()&&!hasLivePlayback(),()->supplementChanged());}catch(Exception ignored){}});}
