 void supplementSettings(){android.content.SharedPreferences prefs=getSharedPreferences("epg-supplement",0);boolean enabled=prefs.getBoolean("enabled",true);new AlertDialog.Builder(this).setTitle("Supplemental guide").setMessage("Exact channel and country matches fill guide gaps. Regional and timeshift names remain separate. Uncertain matches stay empty. Your provider listings take priority except for verified regional corrections tied to the original provider ID. Updates pause during live playback; the last saved guide remains available.").setPositiveButton(enabled?"Disable supplement":"Enable supplement",(d,w)->{prefs.edit().putBoolean("enabled",!enabled).apply();if(supplement!=null){supplement.close();supplement=null;}startSupplement();supplementChanged();}).setNegativeButton("Close",null).show();}
 String timingId(JSONObject ch){String id=ch.optString("epg_channel_id",ch.optString("epg_id",""));return id.isEmpty()?ch.optString("stream_id"):id;}
 String sourceZone(String id){return getSharedPreferences("guide-times",0).getString(favoriteKey()+"_zone_"+id,"UTC");}
 int shiftMinutes(JSONObject ch){return getSharedPreferences("guide-times",0).getInt(favoriteKey()+"_shift_"+timingId(ch),0);}
 void timingSettings(JSONObject ch,Runnable refresh){LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(18),dp(8),dp(18),dp(8));TextView note=label("Source zone applies only when a provider time has no offset. Explicit timestamps stay absolute. All guide times display in your device zone: "+TimeZone.getDefault().getID(),14);form.addView(note);String[] zones={"UTC","America/New_York","America/Chicago","America/Denver","America/Los_Angeles","America/Phoenix","America/Anchorage","Pacific/Honolulu"};Spinner zone=new Spinner(this);zone.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,zones));String id=timingId(ch),saved=sourceZone(id);for(int i=0;i<zones.length;i++)if(zones[i].equals(saved))zone.setSelection(i);form.addView(zone);TextView correction=label("Manual schedule correction (minutes; e.g. -60 or 60)",14);form.addView(correction);EditText offset=new EditText(this);offset.setSingleLine();offset.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);offset.setText(String.valueOf(shiftMinutes(ch)));form.addView(offset);new AlertDialog.Builder(this).setTitle(ch.optString("name","Channel")+" / Time settings").setView(form).setPositiveButton("Save",(d,w)->{try{int minutes=Integer.parseInt(offset.getText().toString());if(Math.abs(minutes)>720)throw new Exception();getSharedPreferences("guide-times",0).edit().putString(favoriteKey()+"_zone_"+id,zones[zone.getSelectedItemPosition()]).putInt(favoriteKey()+"_shift_"+id,minutes).apply();guideLoaded=0;xmlGuide.clear();refresh.run();}catch(Exception e){message("Use a correction between -720 and 720 minutes.");}}).setNeutralButton("Reset",(d,w)->{getSharedPreferences("guide-times",0).edit().remove(favoriteKey()+"_zone_"+id).remove(favoriteKey()+"_shift_"+id).apply();guideLoaded=0;xmlGuide.clear();refresh.run();}).setNegativeButton("Cancel",null).show();}
 void loadXmlGuide()throws Exception{
  long now=System.currentTimeMillis();if(demo||!forceGuideRefresh&&(GuideSnapshot.guideFresh(guideLoaded,now)||guideLoaded>0&&now<guideRetryAfter))return;
  boolean force=forceGuideRefresh;forceGuideRefresh=false;String custom=store.get("xmltv_"+favoriteKey());String url=custom==null?"":custom.trim();
  if(url.isEmpty()){if(m3uMode||server.isEmpty())return;url=server+"/xmltv.php?username="+enc(user)+"&password="+enc(password);}
  File directory=new File(getFilesDir(),"program-guide");if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException("Guide storage unavailable");
  StringBuilder digest=new StringBuilder();for(byte value:java.security.MessageDigest.getInstance("SHA-256").digest(url.getBytes("UTF-8")))digest.append(String.format(Locale.ROOT,"%02x",value&255));
  File cache=new File(directory,favoriteKey()+"_"+digest+".xml.gz");activeGuideFile=cache;File old=new File(getCacheDir(),favoriteKey()+".xml.gz");if(!cache.isFile()&&old.isFile())old.renameTo(cache);
  if(!force&&cache.isFile()){try{xmlGuide=readSavedGuide(cache);guideLoaded=cache.lastModified();if(GuideSnapshot.guideFresh(guideLoaded,now))return;}catch(Exception ignored){}}
  android.content.SharedPreferences checks=getSharedPreferences("daily-guide-checks",0);String checkKey=cache.getName();
  if(!force&&GuideSnapshot.guideFresh(checks.getLong(checkKey,0),now)){guideRetryAfter=checks.getLong(checkKey,0)+EpgSupplement.DAY;return;}
  checks.edit().putLong(checkKey,now).apply();File temp=new File(directory,cache.getName()+".download");HttpURLConnection c=null;
  try{
   guideNetworkChecks++;c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","PiTV/weekly-guide");if(c.getResponseCode()!=200)throw new IOException("EPG HTTP status");
   java.io.PushbackInputStream raw=new java.io.PushbackInputStream(new BufferedInputStream(c.getInputStream()),2);int b1=raw.read(),b2=raw.read();if(b2>=0)raw.unread(b2);if(b1>=0)raw.unread(b1);InputStream input=b1==31&&b2==139?new java.util.zip.GZIPInputStream(raw):raw;
   try(InputStream in=input;OutputStream out=new java.util.zip.GZIPOutputStream(new FileOutputStream(temp))){byte[] bytes=new byte[16384];int n;long total=0;while((n=in.read(bytes))!=-1){total+=n;if(total>256L*1024*1024)throw new IOException("Guide too large");out.write(bytes,0,n);}}
   Map<String,List<XmlGuide.Programme>> updated;try(InputStream in=new java.util.zip.GZIPInputStream(new FileInputStream(temp))){updated=XmlGuide.parse(in,id->sourceZone(id));}
   if(updated.isEmpty())throw new IOException("No usable guide listings");if(!temp.renameTo(cache))throw new IOException("Could not save guide");cache.setLastModified(System.currentTimeMillis());xmlGuide=updated;saveGuideSnapshot(cache);guideLoaded=cache.lastModified();guideRetryAfter=0;
  }catch(Exception e){guideRetryAfter=now+6*3600000L;checks.edit().putLong(checkKey,now-EpgSupplement.DAY+6*3600000L).apply();if(cache.isFile()){xmlGuide=readSavedGuide(cache);guideLoaded=cache.lastModified();runOnUiThread(()->Toast.makeText(this,"Provider unavailable · keeping the saved guide",1).show());}else runOnUiThread(()->Toast.makeText(this,"Guide unavailable · use Refresh program guide to retry",1).show());}
  finally{if(c!=null)c.disconnect();if(temp.isFile())temp.delete();}
 }
 int guideRules(){return getSharedPreferences("guide-times",0).getAll().hashCode();}
 Map<String,List<XmlGuide.Programme>> readSavedGuide(File xml)throws Exception{File snapshot=new File(xml.getPath()+".snapshot.gz");try{Map<String,List<XmlGuide.Programme>> saved=GuideSnapshot.read(snapshot,xml,guideRules());if(saved!=null)return saved;}catch(Exception ignored){}Map<String,List<XmlGuide.Programme>> saved;try(InputStream in=new java.util.zip.GZIPInputStream(new FileInputStream(xml))){saved=XmlGuide.parse(in,id->sourceZone(id));}try{GuideSnapshot.write(snapshot,xml,guideRules(),saved);}catch(Exception ignored){}return saved;}
 void saveGuideSnapshot(File xml){try{GuideSnapshot.write(new File(xml.getPath()+".snapshot.gz"),xml,guideRules(),xmlGuide);}catch(Exception ignored){}}

 List<XmlGuide.Programme> channelProgrammes(JSONObject ch){String id=timingId(ch);List<XmlGuide.Programme> programs=xmlGuide.get(id);if(programs==null)programs=xmlGuide.get(ch.optString("stream_id"));if(supplement!=null&&(supplement.overrides(ch)||!EpgSupplement.usable(programs,System.currentTimeMillis()))){List<XmlGuide.Programme> extra=supplement.get(ch,xmlGuide);if(extra!=null)programs=extra;else if(supplement.overrides(ch))programs=Collections.emptyList();}return programs;}
 JSONArray xmlListings(JSONObject ch)throws Exception{JSONArray result=new JSONArray();List<XmlGuide.Programme> programs=channelProgrammes(ch);if(programs!=null)for(XmlGuide.Programme ep:programs){JSONObject obj=new JSONObject();obj.put("title",android.util.Base64.encodeToString(ep.title.getBytes("UTF-8"),android.util.Base64.NO_WRAP));obj.put("description",android.util.Base64.encodeToString(ep.description.getBytes("UTF-8"),android.util.Base64.NO_WRAP));obj.put("start_timestamp",ep.start/1000);obj.put("stop_timestamp",ep.stop/1000);result.put(obj);}return result;}
 long programmeTime(JSONObject ep,String numeric,String fallback,JSONObject ch){try{long value=Long.parseLong(ep.optString(numeric));if(value>100000000000L)value/=1000;return value*1000L+shiftMinutes(ch)*60000L;}catch(Exception e){String text=ep.optString(fallback,"");try{java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.ROOT);fmt.setLenient(false);fmt.setTimeZone(TimeZone.getTimeZone(sourceZone(timingId(ch))));return fmt.parse(text).getTime()+shiftMinutes(ch)*60000L;}catch(Exception ex){return -1;}}}
 void guideCategories(){load(()->{JSONArray cats=new JSONArray(fetch(api("get_live_categories","")));cacheLanguageGroups(cats);return ()->go(()->{screen("Program guide","Choose a channel group");languageButton(root,()->guideCategories());ArrayList<String> names=new ArrayList<>();ArrayList<Runnable> actions=new ArrayList<>();for(int i=0;i<cats.length();i++){JSONObject cat=cats.optJSONObject(i);if(cat==null)continue;names.add(cat.optString("category_name","Channels"));actions.add(()->{guideGroup=cat.optString("category_name","Current channels");load(()->{JSONArray channels=new JSONArray(fetch(api("get_live_streams","&category_id="+enc(cat.optString("category_id")))));loadXmlGuide();return ()->guidePage(channels,0);});});}rows(names,actions);});});}
