 boolean hasLivePlayback(){return player!=null&&video!=null&&channelQueue!=null&&playbackRoot!=null;}
 void openGuide(){if(hasLivePlayback()){if(guideOverPlayback&&cableScreen!=null){cableScreen.gridFocus();return;}showPlayingGuide(liveSource!=null?liveSource:channelQueue);return;}if(cableScreen!=null){cableScreen.gridFocus();return;}if(channelQueue!=null){liveChannels(channelQueue);return;}openLive(false);}
 void showPlayingGuide(JSONArray source){if(!hasLivePlayback())return;boolean returningFromFullScreen=!guideOverPlayback;if(returningFromFullScreen&&playbackGuide!=null&&!playbackGuide.containsChannel(playingId)){playbackGuide.saveBookmark();liveGroup=playingGroup;liveGroupName=playingGroupName;source=channelQueue;liveSource=source;}guideOverPlayback=true;dashboardScreen=false;if(playbackGuide==null){playbackGuide=new CableGuideScreen(this,source);playbackRoot.addView(playbackGuide,new FrameLayout.LayoutParams(-1,-1));playbackGuide.getViewTreeObserver().addOnGlobalLayoutListener(this::placeGuidePlayer);}else playbackGuide.bindSource(source);CableGuideScreen guide=playbackGuide;cableScreen=guide;guidePreview=guide.preview;activeProgramGuide=guide.grid;guide.setVisibility(View.VISIBLE);guide.preview.suspend();if(returningFromFullScreen)player.keepGuideAudio=true;player.setMiniMode(true);player.setOnClickListener(v->fullScreenPlayback());player.bringToFront();guide.preview.post(()->placeGuidePlayer());if(returningFromFullScreen)guide.focusChannel(playingId);guide.gridFocus();guide.grid.notifySelection();}
 void placeGuidePlayer(){if(!guideOverPlayback||playbackGuide==null||!hasLivePlayback())return;View target=playbackGuide.preview;if(target.getWidth()==0||target.getHeight()==0)return;int[] location=new int[2],origin=new int[2];target.getLocationInWindow(location);playbackRoot.getLocationInWindow(origin);FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)player.getLayoutParams();int left=location[0]-origin[0],top=location[1]-origin[1];if(p.width!=target.getWidth()||p.height!=target.getHeight()||p.leftMargin!=left||p.topMargin!=top){FrameLayout.LayoutParams next=new FrameLayout.LayoutParams(target.getWidth(),target.getHeight());next.leftMargin=left;next.topMargin=top;player.setLayoutParams(next);}if(playbackRoot.getChildAt(playbackRoot.getChildCount()-1)!=player)player.bringToFront();}
