 void previewChannelFromGuide(JSONArray channels,int index){ProgramGuideView previous=cableScreen==null?null:cableScreen.grid;int first=previous==null?0:previous.firstRow;long time=previous==null?System.currentTimeMillis():previous.selectedTime,window=previous==null?time/(30*GuideModel.MINUTE)*(30*GuideModel.MINUTE):previous.window;boolean follow=previous==null||previous.followNow;String selected=channels.optJSONObject(index)==null?"":channels.optJSONObject(index).optString("stream_id");rememberChannel();channelQueue=channels;channelIndex=index;liveSelection=index;current=()->playChannel();tuningGuidePreview=true;try{playChannel();}finally{tuningGuidePreview=false;}openGuide();if(cableScreen!=null){ProgramGuideView restored=cableScreen.grid;for(int row=0;row<cableScreen.model.size();row++){JSONObject item=cableScreen.channels.optJSONObject(cableScreen.model.get(row).sourceIndex);if(item!=null&&selected.equals(item.optString("stream_id"))){restored.row=row;break;}}restored.firstRow=first;restored.selectedTime=time;restored.window=window;restored.followNow=follow;restored.keepVisible();restored.notifySelection();restored.requestFocus();}}
