 List<GuideModel.Program> lazyPrograms(JSONObject channel){List<XmlGuide.Programme> entries=channelProgrammes(channel);if(entries==null||entries.isEmpty())return new ArrayList<>();final List<XmlGuide.Programme> saved=entries;final long shift=shiftMinutes(channel)*60000L;return new AbstractList<GuideModel.Program>(){GuideModel.Program[] prepared;public int size(){return saved.size();}public GuideModel.Program get(int index){if(prepared==null)prepared=new GuideModel.Program[saved.size()];if(prepared[index]==null){XmlGuide.Programme ep=saved.get(index);prepared[index]=new GuideModel.Program(ep.start+shift,ep.stop+shift,ep.title,ep.description);}return prepared[index];}};}
 List<GuideModel.Program> guidePrograms(JSONObject channel,JSONArray listings){ArrayList<GuideModel.Program> programs=new ArrayList<>();for(int i=0;i<listings.length();i++){JSONObject ep=listings.optJSONObject(i);if(ep==null)continue;long start=programmeTime(ep,"start_timestamp","start",channel),end=programmeTime(ep,"stop_timestamp","end",channel);if(start>=0&&end>start)programs.add(new GuideModel.Program(start,end,decodeGuide(ep.optString("title")),decodeGuide(ep.optString("description"))));}Collections.sort(programs,(x,y)->Long.compare(x.start,y.start));return programs;}
