 void showProgramGuide(JSONArray source,List<GuideModel.Channel> model,int offset){if(programGuideDialog!=null&&programGuideDialog.isShowing())return;Dialog dialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar);programGuideDialog=dialog;LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(22),dp(14),dp(22),dp(12));panel.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff263853,0xff29263f,0xff26152d}));dialog.setContentView(panel);TextView guideBrand=label("EPG  /  "+guideGroup+"      "+android.text.format.DateFormat.format("h:mm a  |  MMM d",new Date()),18);guideBrand.setPadding(dp(6),0,0,dp(8));panel.addView(guideBrand);LinearLayout controls=new LinearLayout(this);Button day=TvStyle.button(this,"Today ▾",()->{}),time=TvStyle.button(this,"Time ▾",()->{}),live=TvStyle.button(this,"Jump to live",()->{}),refresh=TvStyle.button(this,"Refresh",()->{}),timing=TvStyle.button(this,"Channel time",()->{}),close=TvStyle.button(this,"Close",()->dialog.dismiss());for(Button button:new Button[]{day,time,live,refresh,timing,close}){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(42),1);lp.setMargins(dp(3),0,dp(3),0);controls.addView(button,lp);}panel.addView(controls);TextView date=label("",12);date.setTextColor(0xffa8afc7);date.setPadding(0,dp(10),0,dp(6));panel.addView(date);LinearLayout details=new LinearLayout(this);details.setOrientation(1);details.setPadding(dp(14),dp(9),dp(14),dp(7));details.setBackgroundColor(Color.TRANSPARENT);TextView selectedTitle=label("",21),selectedTime=label("",13),selectedDescription=label("",13);selectedTitle.setMaxLines(1);selectedTime.setMaxLines(1);selectedTime.setTextColor(0xffc4b6ff);selectedDescription.setMaxLines(2);details.addView(selectedTitle);details.addView(selectedTime);details.addView(selectedDescription);LinearLayout overview=new LinearLayout(this);GuidePreview preview=new GuidePreview(this);guidePreview=preview;preview.setBackground(TvStyle.shape(this,0xff101827,0xff344760));preview.setContentDescription("Selected channel logo");LinearLayout.LayoutParams previewLp=new LinearLayout.LayoutParams(dp(165),-1);previewLp.rightMargin=dp(12);overview.addView(preview,previewLp);overview.addView(details,new LinearLayout.LayoutParams(0,-1,1));panel.addView(overview,new LinearLayout.LayoutParams(-1,dp(100)));Set<String> requestedLogos=new HashSet<>(),requestedShort=new HashSet<>();final ProgramGuideView[] guide={null};ProgramGuideView.Host host=new ProgramGuideView.Host(){public void selected(GuideModel.Channel ch,GuideModel.Program programme){selectedTitle.setText(programme==null?ch.name:programme.title);selectedTime.setText(programme==null?ch.name:ch.name+"  ·  "+android.text.format.DateFormat.getTimeFormat(IptvActivity.this).format(new Date(programme.start))+" – "+android.text.format.DateFormat.getTimeFormat(IptvActivity.this).format(new Date(programme.end))+(programme.start<=System.currentTimeMillis()&&programme.end>System.currentTimeMillis()?"  ·  Playing now":""));selectedDescription.setText(programme==null?"":programme.description);preview.setImageBitmap(images.get(ch.logo==null?"":ch.logo));if(!demo){try{preview.tune(channelAddress(source.optJSONObject(ch.sourceIndex)));}catch(Exception ignored){}}if(ch.logo!=null&&ch.logo.startsWith("http")&&requestedLogos.add("preview:"+ch.logo)){String logoUrl=ch.logo;artwork.submit(()->{try{android.graphics.Bitmap bitmap=poster(logoUrl);if(bitmap!=null){images.put(logoUrl,bitmap);runOnUiThread(()->{if(dialog.isShowing()&&selectedTitle.getText().length()>0)guide[0].notifySelection();});}}catch(Exception ignored){}});}long at=guide[0]==null?System.currentTimeMillis():guide[0].window;date.setText(android.text.format.DateFormat.format("EEEE, MMM d",new Date(at))+"  /  "+TimeZone.getDefault().getID()+"  /  "+model.size()+" channels"+(activeGuideFile!=null&&activeGuideFile.isFile()?"  /  EPG saved "+android.text.format.DateFormat.format("MMM d",new Date(activeGuideFile.lastModified()))+" · weekly":""));}
 public void activate(GuideModel.Channel ch,GuideModel.Program programme){if(demo){message("Connect your provider to watch");return;}Runnable tune=()->{dialog.dismiss();rememberChannel();channelQueue=source;channelIndex=ch.sourceIndex;go(()->playChannel());};if(programme==null||programme.start<=System.currentTimeMillis()&&programme.end>System.currentTimeMillis())tune.run();else new AlertDialog.Builder(IptvActivity.this).setTitle(programme.title).setMessage(android.text.format.DateFormat.getTimeFormat(IptvActivity.this).format(new Date(programme.start))+" – "+android.text.format.DateFormat.getTimeFormat(IptvActivity.this).format(new Date(programme.end))+"\n\n"+programme.description).setPositiveButton("Watch channel live",(d,w)->tune.run()).setNegativeButton("Close",null).show();}
 public android.graphics.Bitmap logo(String url,Runnable ready){if(url==null||url.isEmpty())return null;android.graphics.Bitmap cached=images.get(url);if(cached!=null)return cached;if(url.startsWith("http")&&requestedLogos.add(url))artwork.submit(()->{try{android.graphics.Bitmap bitmap=poster(url);if(bitmap!=null){images.put(url,bitmap);runOnUiThread(()->{if(dialog.isShowing())ready.run();});}}catch(Exception ignored){}});return null;}};guide[0]=new ProgramGuideView(this,model,host);activeProgramGuide=guide[0];guide[0].row=Math.min(Math.max(0,offset),Math.max(0,model.size()-1));panel.addView(guide[0],new LinearLayout.LayoutParams(-1,0,1));TextView hint=label("↑↓ Channels    ←→ Time    OK Watch / program details    Back Close",11);hint.setTextColor(0xffa8afc7);hint.setPadding(0,dp(6),0,0);panel.addView(hint);day.setOnClickListener(v->{String[] days=new String[8];for(int i=0;i<days.length;i++){Calendar c=Calendar.getInstance();c.add(Calendar.DAY_OF_YEAR,i-1);days[i]=i==1?"Today":i==2?"Tomorrow":android.text.format.DateFormat.format("EEE, MMM d",c).toString();}new AlertDialog.Builder(this).setTitle("Choose day").setItems(days,(d,index)->{Calendar c=Calendar.getInstance();c.setTimeInMillis(guide[0].selectedTime);int hour=c.get(Calendar.HOUR_OF_DAY),minute=c.get(Calendar.MINUTE);c=Calendar.getInstance();c.add(Calendar.DAY_OF_YEAR,index-1);c.set(Calendar.HOUR_OF_DAY,hour);c.set(Calendar.MINUTE,minute);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);guide[0].jump(c.getTimeInMillis());day.setText(days[index]+" ▾");guide[0].requestFocus();}).show();});time.setOnClickListener(v->{String[] labels={"Midnight · 12 AM","Morning · 6 AM","Afternoon · 12 PM","Evening · 6 PM","Prime time · 8 PM"};int[] hours={0,6,12,18,20};new AlertDialog.Builder(this).setTitle("Jump to time").setItems(labels,(d,index)->{Calendar c=Calendar.getInstance();c.setTimeInMillis(guide[0].selectedTime);c.set(Calendar.HOUR_OF_DAY,hours[index]);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);guide[0].jump(c.getTimeInMillis());time.setText(labels[index]+" ▾");guide[0].requestFocus();}).show();});live.setOnClickListener(v->{guide[0].jump(System.currentTimeMillis());day.setText("Today ▾");time.setText("Time ▾");guide[0].requestFocus();});refresh.setOnClickListener(v->{int index=guide[0].row;dialog.dismiss();guideLoaded=0;forceGuideRefresh=true;guidePageClean(source,index);});timing.setOnClickListener(v->{if(model.isEmpty())return;int index=guide[0].row;JSONObject ch=source.optJSONObject(model.get(index).sourceIndex);dialog.dismiss();timingSettings(ch,()->guidePageClean(source,index));});if(channelPreview!=null)channelPreview.stopPlayback();if(player!=null)player.suspend();dialog.setOnDismissListener(d->{if(programGuideDialog==dialog){programGuideDialog=null;activeProgramGuide=null;}preview.suspend();if(guidePreview==preview)guidePreview=null;if(player!=null)player.resume();else if(channelPreview!=null&&!previewUrl.isEmpty())channelPreview.setVideoURI(Uri.parse(previewUrl));});dialog.show();dialog.getWindow().setLayout(-1,-1);dialog.getWindow().getDecorView().setSystemUiVisibility(5894);guide[0].requestFocus();guide[0].keepVisible();guide[0].notifySelection();}
 String decodeGuide(String value){try{return new String(android.util.Base64.decode(value,android.util.Base64.DEFAULT),"UTF-8");}catch(Exception e){return value;}}
 String guideTime(JSONObject e,String numeric,String fallback){try{long seconds=Long.parseLong(e.optString(numeric));return android.text.format.DateFormat.getTimeFormat(this).format(new java.util.Date(seconds*1000));}catch(Exception ex){return e.optString(fallback,"");}}
 void guide(String id){if(demo){message("Program guide data is loaded from your provider after you connect.");return;}load(()->{JSONArray data=shortSchedule(id);StringBuilder body=new StringBuilder();if(data!=null)for(int i=0;i<data.length();i++){JSONObject e=data.optJSONObject(i);if(e==null)continue;body.append(guideTime(e,"start_timestamp","start")).append(" – ").append(guideTime(e,"stop_timestamp","end")).append("\n").append(decodeGuide(e.optString("title"))).append("\n");String desc=decodeGuide(e.optString("description"));if(!desc.isEmpty())body.append(desc).append("\n");body.append("\n");}String result=body.length()==0?"No saved schedule is available for this channel.":body.toString();return ()->new AlertDialog.Builder(this).setTitle("Program guide").setMessage(result).setPositiveButton("Close",null).show();});}
 @Override public boolean dispatchKeyEvent(KeyEvent e){if(hasLivePlayback()&&!guideOverPlayback&&player.overlay.getVisibility()!=View.VISIBLE&&e.getKeyCode()==KeyEvent.KEYCODE_DPAD_LEFT){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)showChannelMenu();return true;}if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getKeyCode()==KeyEvent.KEYCODE_GUIDE&&hasLivePlayback()){if(e.getRepeatCount()==0)openGuide();return true;}if(video!=null&&channelQueue!=null&&e.getAction()==KeyEvent.ACTION_DOWN&&e.getKeyCode()>=KeyEvent.KEYCODE_0&&e.getKeyCode()<=KeyEvent.KEYCODE_9){if(e.getRepeatCount()==0){if(channelDigits.length()>=4)channelDigits="";channelDigits+=String.valueOf(e.getKeyCode()-KeyEvent.KEYCODE_0);Toast.makeText(this,"Channel "+channelDigits,0).show();channelKeyHandler.removeCallbacks(channelNumberTune);channelKeyHandler.postDelayed(channelNumberTune,1000);}return true;}if(video==null&&dashboardScreen&&e.getAction()==KeyEvent.ACTION_DOWN&&e.getKeyCode()==KeyEvent.KEYCODE_GUIDE){if(e.getRepeatCount()==0)openGuide();return true;}if(video!=null&&!guideOverPlayback&&e.getAction()==KeyEvent.ACTION_DOWN){if(e.getKeyCode()==KeyEvent.KEYCODE_CHANNEL_UP||e.getKeyCode()==KeyEvent.KEYCODE_CHANNEL_DOWN){if(e.getRepeatCount()==0)changeChannel(e.getKeyCode()==KeyEvent.KEYCODE_CHANNEL_UP?1:-1);return true;}if(e.getKeyCode()==KeyEvent.KEYCODE_GUIDE){if(e.getRepeatCount()==0)openGuide();return true;}if(e.getKeyCode()==KeyEvent.KEYCODE_LAST_CHANNEL||e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PREVIOUS){if(e.getRepeatCount()==0)recallChannel();return true;}}return super.dispatchKeyEvent(e);}
 @Override public void onBackPressed(){
  if(catalogReturn!=null&&channelQueue==null){returnToCatalog();return;}
  if(!guideOverPlayback&&player!=null&&player.dismissPlaybackOverlay())return;
  back();
 }
 void savePosition(){if(demo||video==null||lastUrl.isEmpty()||channelQueue!=null)return;try{JSONObject obj=new JSONObject();obj.put("name",lastName);obj.put("url",lastUrl);obj.put("position",Math.max(0,video.getCurrentPosition()));if(episodeQueue!=null){obj.put("episodes",episodeQueue);obj.put("episodeIndex",episodeIndex);}store.put("last_"+favoriteKey(),obj.toString());}catch(Exception ignored){}}
 @Override protected void onResume(){super.onResume();if(velvetNeedsReload){velvetNeedsReload=false;if(playbackGuide!=null)playbackGuide.setVisibility(View.VISIBLE);openLive(false);}foreground=this;savedGuideClock.removeCallbacks(savedGuideTick);savedGuideClock.postDelayed(savedGuideTick,60000);if(guidePreview!=null)guidePreview.resume();if(channelPreview!=null&&!previewUrl.isEmpty()){channelPreview.setVideoURI(Uri.parse(previewUrl));}if(player!=null)player.resume();}
 @Override protected void onPause(){if(velvetPin!=null)velvetPin.dismiss();if(velvetUnlocked||liveGroup.equals("@adults")){velvetNeedsReload=leaveVelvet();if(playbackGuide!=null)playbackGuide.setVisibility(View.GONE);}if(playbackGuide!=null)playbackGuide.saveBookmark();if(foreground==this)foreground=null;savedGuideClock.removeCallbacks(savedGuideTick);super.onPause();if(guidePreview!=null)guidePreview.suspend();if(previewTune!=null)previewHandler.removeCallbacks(previewTune);if(channelPreview!=null)channelPreview.stopPlayback();savePosition();if(player!=null)player.suspend();}
 @Override protected void onDestroy(){savedGuideClock.removeCallbacks(savedGuideTick);channelKeyHandler.removeCallbacksAndMessages(null);generation++;if(guidePreview!=null)guidePreview.suspend();stopChannelPreview();if(video!=null)video.stopPlayback();if(supplement!=null)supplement.close();worker.shutdownNow();guideWorker.shutdownNow();artwork.shutdownNow();images.evictAll();user="";password="";super.onDestroy();}
